param(
  [string]$ProjectRoot = "D:\simras-digital-twin-repository\simras-digital-twin"
)

$ErrorActionPreference = "Stop"
Set-Location $ProjectRoot
[Environment]::CurrentDirectory = (Get-Location).Path

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $ProjectRoot "archive\infrastructure_real_data_$stamp"
New-Item -ItemType Directory -Force $backup | Out-Null

$target = ".\frontend\src\pages\infrastructure\InfrastructurePages.tsx"

if (Test-Path $target) {
  Copy-Item $target (Join-Path $backup "InfrastructurePages.tsx") -Force
}

Write-Host "`n============================================================" -ForegroundColor Cyan
Write-Host "SIMRAS INFRASTRUCTURE REAL-DATA FIX" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

Write-Host "`n=== 1. DATABASE COUNT ===" -ForegroundColor Cyan
docker compose exec -T db sh -lc 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "SELECT COUNT(*) FROM assets;"' 2>$null

Write-Host "`n=== 2. BACKEND ENDPOINTS ===" -ForegroundColor Cyan
foreach ($url in @(
  "http://localhost:8000/api/v1/infrastructure?limit=3",
  "http://localhost:8000/api/v1/assets?limit=3",
  "http://localhost:8000/api/v1/gis/assets?limit=3",
  "http://localhost:8000/api/v1/map/features?limit=3"
)) {
  $code = curl.exe -s -o NUL -w "%{http_code}" $url
  Write-Host "$code  $url"
}

Write-Host "`n=== 3. INSTALL REAL-DATA PAGE ===" -ForegroundColor Cyan

[IO.File]::WriteAllBytes(
  $target,
  [Convert]::FromBase64String("")
)

Write-Host "InfrastructurePages.tsx replaced with live-data version." -ForegroundColor Green
Write-Host "Backup: $backup" -ForegroundColor DarkGray

Write-Host "`n=== 4. FRONTEND BUILD ===" -ForegroundColor Cyan

Push-Location ".\frontend"
npm run build
$buildExit = $LASTEXITCODE
Pop-Location

if ($buildExit -ne 0) {
  Write-Host "Running frontend container was NOT replaced." -ForegroundColor Yellow
  throw "FRONTEND BUILD FAILED - SEND ONLY THE FIRST NEW ERROR"
}

Write-Host "FRONTEND BUILD PASS" -ForegroundColor Green

Write-Host "`n=== 5. REBUILD FRONTEND ===" -ForegroundColor Cyan
docker compose stop frontend
docker compose rm -f frontend
docker compose up -d --build --force-recreate --renew-anon-volumes frontend

Start-Sleep -Seconds 7

Write-Host "`n=== 6. LIVE CHECK ===" -ForegroundColor Cyan

$front = curl.exe -s -o NUL -w "%{http_code}" "http://localhost:5173/infrastructure"
$api = curl.exe -s -o NUL -w "%{http_code}" "http://localhost:8000/api/v1/infrastructure?limit=3"

Write-Host "Infrastructure page : $front"
Write-Host "Infrastructure API  : $api"

Write-Host "`n=== 7. REAL API SAMPLE ===" -ForegroundColor Cyan
curl.exe -s "http://localhost:8000/api/v1/infrastructure?limit=3" |
  py -c "import sys,json; d=json.load(sys.stdin); x=d.get('items',d if isinstance(d,list) else []); print('total=',d.get('total',len(x)) if isinstance(d,dict) else len(x)); [print(a.get('asset_code') or a.get('asset_id') or a.get('id'), '|', a.get('name'), '|', a.get('asset_type') or a.get('type'), '|', a.get('district')) for a in x[:3]]"

Write-Host "`n============================================================" -ForegroundColor Green
Write-Host "INFRASTRUCTURE REAL-DATA CONNECTION APPLIED" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "No mock fallback is used."
Write-Host "Missing health/risk/RUL values display N/A."
Write-Host "Real asset types are preserved."
Write-Host "Add Asset fake/demo workflow was removed."

Start-Process "http://localhost:5173/infrastructure"
